static class MobilityRecovery {
    long lastTime = -100, lastContact = -100, until = -1, cooldown = -1;
    double lastX, lastY, blockX, blockY;
    int blocked, contacts, recoveries;
    void contact(long time, double x, double y) {
        contacts = time - lastContact <= 12 ? contacts + 1 : 1;
        lastContact = time; blockX = x; blockY = y;
    }
    boolean active(long time) {return time < until;}
    boolean observe(long time, double x, double y, double velocity, boolean intended) {
        boolean consecutive = time == lastTime + 1;
        boolean stopped = intended && Math.abs(velocity) < 0.3 && Math.hypot(x-lastX,y-lastY) < 0.35;
        blocked = consecutive && stopped ? blocked + 1 : 0;
        lastTime = time; lastX = x; lastY = y;
        if (time - lastContact > 12) contacts = 0;
        if (time < cooldown || active(time) || (blocked < 8 && contacts < 3)) return false;
        blockX = x; blockY = y; until = time + 18; cooldown = time + 40;
        blocked = contacts = 0; recoveries++;return true;
    }
}

static boolean rayObstacle(double along, double perpendicular, double distance, double radius) {
    return along > 36 && along < distance - 20 && Math.abs(perpendicular) < radius;
}

private Enemy firstBlocker(Enemy intended, double aim, double distance, double speed) {
    Enemy nearest = null;double nearestAlong = distance;
    double ux = Math.sin(aim), uy = Math.cos(aim);
    for (Enemy other : enemies.values()) {
        long age = getTime() - other.time;
        if (other == intended || !other.alive || age < 0 || age > 4) continue;
        double along = (other.x-getX())*ux + (other.y-getY())*uy;
        MotionState predicted = null;
        for (int iteration = 0; iteration < 3; iteration++) {
            predicted = new MotionState(other.x,other.y,other.heading,other.velocity);
            int flight = (int)Math.round(clamp(0, age + along/speed, 40));
            for (int t = 0; t < flight; t++) predicted.step(other.turnRate,other.velocity,width,height);
            along = (predicted.x-getX())*ux + (predicted.y-getY())*uy;
        }
        double perpendicular = (predicted.x-getX())*uy - (predicted.y-getY())*ux;
        double radius = 20 - Math.min(6, age + Math.max(0,along/speed)*0.12);
        if (rayObstacle(along,perpendicular,distance,radius) && along < nearestAlong) {
            nearest = other;nearestAlong = along;
        }
    }
    return nearest;
}

